cd /workspace/target && cat > src/codes.py <<'EOF'
"""The diagnosis codes recorded on an encounter."""
from __future__ import annotations

import math

import pandas as pd

BLANKS = ("", "nan", "None", "NaN", "<NA>")


def _as_charted(value) -> str:
    """One cell, as the coder charted it.

    A diagnosis column that happens to carry no missing marker is parsed as a number by
    `read_csv`, which would turn the charted `428` into `428.0` and quietly invent a code the
    code table has never seen. Numbers are rendered back to the charted text; everything else
    is left exactly as it stands, decimal subdivisions and V/E series included.
    """
    if value is None:
        return ""
    if isinstance(value, float):
        if math.isnan(value):
            return ""
        if value.is_integer():
            return str(int(value))
        return repr(value)
    if isinstance(value, int):
        return str(value)
    return str(value).strip()


def normalise(raw: pd.Series, missing: str = "?") -> pd.Series:
    """Recorded diagnosis codes, tidied for use as register entries.

    The missing marker and blank cells come back as NaN so they never reach a register.
    Everything else is kept as charted, which is what the code table is keyed on.
    """
    text = raw.map(_as_charted)
    return text.where(~text.isin((missing, *BLANKS)))
